import {mock} from 'node:test';
import cp from 'node:child_process';
import {syncBuiltinESMExports} from 'node:module';
const source=new URL(process.argv[2]),fixtures=new URL(process.argv[4]);
const [{StructureParser},{TemplateScriptParser},frames]=await Promise.all([import(new URL('analysis/tree-sitter/client.js',source)),import(new URL('analysis/tree-sitter/template-scripts.js',source)),import(new URL('analysis/tree-sitter/frames.js',source))]);
const {encodeParserFrame,decodeParserFrame,ParserFrameLimitError,PARSER_FRAME_BYTES}=frames,observations=[],children=[],fork=cp.fork;
const observer=mock.method(cp,'fork',(...args)=>{for(const child of children)assert.ok(child.exitCode!==null||child.signalCode!==null,'Previous parser address space must retire');const child=Reflect.apply(fork,cp,args);children.push(child);return child;});syncBuiltinESMExports();
try{
 const proof={source:'é😀\r\n\ud800',optional:undefined},facts={proof,alias:proof,map:new Map([['original',proof]]),binary:Buffer.from([0,255,7]),values:[undefined,-0,NaN,Infinity]};facts.self=facts;
 const decoded=decodeParserFrame(encodeParserFrame({facts}));assert.deepEqual(serialize(decoded),serialize(deserialize(serialize({facts}))));assert.equal(decoded.facts.proof,decoded.facts.alias);assert.equal(decoded.facts.self,decoded.facts);observations.push({case:'complete-original-fields-and-aliases',exactBinaryEquality:true});
 for(const value of ['é😀'.repeat(8192),Buffer.alloc(32768)]){const stats={};assert.throws(()=>encodeParserFrame({facts:value},4096,stats),ParserFrameLimitError);assert.ok(stats.allocatedBlockBytes<=4096);assert.equal(stats.concatenatedBytes,0);}observations.push({case:'encoding-allocation-admission',selectedBytes:4096,stringAndBinaryRejectedBeforeFinalConcatenation:true});
 const compact=encodeParserFrame({facts:Array(1_000_000)}),stats={};assert.ok(compact.length<100);assert.throws(()=>decodeParserFrame(compact,PARSER_FRAME_BYTES,stats,{arraySlots:16}),ParserFrameLimitError);assert.equal(stats.arraySlots,0);observations.push({case:'compact-decoded-structure-admission',originalSlots:1_000_000,selectedSlots:16,encodedBytes:compact.length,decodedSlotsAllocated:0});
 const control=new StructureParser(1500,fileURLToPath(new URL('parser-response-control.mjs',fixtures)),[],false);
 try{let original=await control.parse('owned','healthy');for(const [input,pattern] of [['oversized',/Parser response exceeds 67108864 bytes/],['unknown-encoding',/Invalid parser response encoding/],['changed-encoding',/Invalid parser response/]]){await assert.rejects(control.parse('owned',input),pattern);const recovered=await control.parse('owned','healthy');assert.notEqual(recovered.pid,original.pid);original=recovered;}observations.push({case:'protocol-failures-and-real-retirement',rejectedOriginalInputs:3,ordinaryReuseCannotRetainFaultedWorker:true});}finally{await control.closeAndWait();}
 const native=new StructureParser();
 try{const original='// original é😀\r\nint original(void){return 1;}\r\n';const first=await native.parse('c',original,{nativeOnly:true});assert.ok(first.declarations.some(row=>row.name==='original'));assert.deepEqual(await native.parse('c',original,{nativeOnly:true}),first);observations.push({case:'actual-native-bounded-requests-and-facts',originalDeclarationsPreserved:true});
  await assert.rejects(native.parse('owned-input-limit','x'.repeat(PARSER_FRAME_BYTES+1),{nativeOnly:true}),/Parser facts payload exceeds 67108864 bytes/);assert.deepEqual(await native.parse('c',original,{nativeOnly:true}),first);observations.push({case:'actual-request-byte-admission-and-recovery',originalSourceUnits:PARSER_FRAME_BYTES+1,reapedBeforeNextParse:true});
 }finally{await native.closeAndWait();}
 const original='<script>function original(){return "é😀"}</script>\n',parser=new StructureParser(),scripts=new TemplateScriptParser();
 try{const before=await parser.parse('erb',original,{nativeOnly:true,erbHost:'html'});await parser.closeAndWait();const completed=await scripts.finish(original,before);assert.ok(completed.declarations.some(row=>row.name==='original'&&row.range.startLine===1));assert.equal(before.declarations.some(row=>row.name==='original'),false);observations.push({case:'actual-native-to-literal-script-transfer',completeSourceCoordinates:true,parentFactsUnchanged:true});}finally{await parser.closeAndWait();await scripts.closeAndWait();}
 assert.equal(observations.length,7);assert.equal(children.length,8);assert.ok(children.every(child=>child.exitCode!==null||child.signalCode!==null));
 const receipt={schema:1,passed:true,node:process.version,sourceLoader:process.execArgv.some(arg=>/tsx/.test(arg)),caseCount:7,frameBytes:PARSER_FRAME_BYTES,observations,actualWorkers:children.map(child=>({pid:child.pid,code:child.exitCode,signal:child.signalCode})),actualAddressSpacesRetired:true,targetExecution:false,totalRssQualified:false,scope:'Actual bounded native/template requests and replies, exact fields/aliases, bytes/logical structure, protocol failure retirement and raw oversized request recovery. Explicit alternate provider fixtures retain their legacy V8 transport. Parent graph ownership, Object.keys admission, decoded physical memory and total RSS remain separate.'};await writeFile(process.argv[3],JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({passed:true,node:receipt.node,caseCount:7,actualWorkers:children.length,sourceLoader:receipt.sourceLoader}));
}finally{observer.mock.restore();syncBuiltinESMExports();}
